# Implement m3: Support callable into in @reraise
with open('funcy/flow.py') as f:
    content = f.read()

old_reraise = '''@contextmanager
def reraise(errors, into):
    """Reraises errors as other exception."""
    errors = _ensure_exceptable(errors)
    try:
        yield
    except errors as e:
        raise_from(into, e)'''

new_reraise = '''@contextmanager
def reraise(errors, into):
    """Reraises errors as other exception."""
    errors = _ensure_exceptable(errors)
    try:
        yield
    except errors as e:
        if callable(into):
            into = into(e)
        raise_from(into, e)'''

if old_reraise in content:
    content = content.replace(old_reraise, new_reraise)
    with open('funcy/flow.py', 'w') as f:
        f.write(content)
    print("m3: Successfully updated flow.py")
else:
